#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.TodayRequest;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Once the sheet's new today is set: while it has grace days, close each open period (not a soft-closed one) whose to-date plus them is
 *  before the new today, in order of their to-dates, exactly as a close by hand would, each recorded as
 *  PERIOD_CLOSED with auto=yes at its end. */
public class AutoClosePeriods {
    public void close(@PathVariable("sheetId") String sheetId, @Val TodayRequest request, @Val LocalDate today,
            PeriodRepository periods, ClaimRepository claims, ClaimLogRepository logs, PersonRepository people,
            RateRepository rates, SettingRepository settings, SheetRepository sheets, Audit audit)
            throws InvalidPeriodException {
        String id = sheetId.trim();
        Integer grace = settings.graceDays(id);
        if (grace == null) {
            return;
        }
        periods.lockSheet(id);
        var due = periods.list(id).stream()
                .filter(p -> !p.closed() && !p.soft() && p.to().plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to))
                .toList();
        for (Period period : due) {
            Period closed = PeriodCloser.fix(id, period, periods, claims, logs, people, rates, settings, sheets);
            audit.record("PERIOD_CLOSED sheet=" + closed.sheetId() + " by=" + request.user()
                    + " period=" + closed.name() + " total=" + closed.closedTotal().toPlainString() + " auto=yes");
        }
    }
}

